local Players = game:GetService("Players") local RunService = game:GetService("RunService") local LocalPlayer = Players.LocalPlayer if game:GetService("CoreGui"):FindFirstChild("DeltaGodMenu") then game:GetService("CoreGui").DeltaGodMenu:Destroy() end local SystemConfig = {TargetName = "", TpEnabled = false, KickEnabled = false, KickForce = 12345678, OriginalLocation = nil} local function Notify(title, text) game:GetService("StarterGui"):SetCore("SendNotification", {Title = title, Text = text, Duration = 2}) end local function GetPlayerByUsername(username) return Players:FindFirstChild(username) end local ScreenGui = Instance.new("ScreenGui") local MainFrame = Instance.new("Frame") local TitleLabel = Instance.new("TextLabel") local SelectedTargetLabel = Instance.new("TextLabel") local ListButton = Instance.new("TextButton") local DropdownFrame = Instance.new("ScrollingFrame") local UIListLayout = Instance.new("UIListLayout") local TpButton = Instance.new("TextButton") local KickButton = Instance.new("TextButton") local InstantButton = Instance.new("TextButton") ScreenGui.Name = "DeltaGodMenu" ScreenGui.Parent = game:GetService("CoreGui") ScreenGui.ResetOnSpawn = false MainFrame.Name = "MainFrame" MainFrame.Parent = ScreenGui MainFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 30) MainFrame.Position = UDim2.new(0.05, 0, 0.25, 0) MainFrame.Size = UDim2.new(0, 230, 0, 310) MainFrame.BorderSizePixel = 0 MainFrame.Active = true MainFrame.Draggable = true TitleLabel.Name = "TitleLabel" TitleLabel.Parent = MainFrame TitleLabel.BackgroundColor3 = Color3.fromRGB(35, 35, 50) TitleLabel.Size = UDim2.new(1, 0, 0, 35) TitleLabel.Font = Enum.Font.SourceSansBold TitleLabel.Text = "💎 DELTA GOD MENU v2" TitleLabel.TextColor3 = Color3.fromRGB(255, 255, 255) TitleLabel.TextSize = 15 SelectedTargetLabel.Name = "SelectedTargetLabel" SelectedTargetLabel.Parent = MainFrame SelectedTargetLabel.BackgroundTransparency = 1 SelectedTargetLabel.Position = UDim2.new(0.05, 0, 0.13, 0) SelectedTargetLabel.Size = UDim2.new(0.9, 0, 0, 25) SelectedTargetLabel.Font = Enum.Font.SourceSansItalic SelectedTargetLabel.Text = "เป้าหมาย: [ยังไม่ได้เลือก]" SelectedTargetLabel.TextColor3 = Color3.fromRGB(255, 215, 0) SelectedTargetLabel.TextSize = 14 SelectedTargetLabel.TextXAlignment = Enum.TextXAlignment.Left ListButton.Name = "ListButton" ListButton.Parent = MainFrame ListButton.BackgroundColor3 = Color3.fromRGB(45, 45, 60) ListButton.Position = UDim2.new(0.05, 0, 0.23, 0) ListButton.Size = UDim2.new(0.9, 0, 0, 35) ListButton.Font = Enum.Font.SourceSansBold ListButton.Text = "🔽 เลือกรายชื่อผู้เล่นในแมพ" ListButton.TextColor3 = Color3.fromRGB(255, 255, 255) ListButton.TextSize = 14 TpButton.Name = "TpButton" TpButton.Parent = MainFrame TpButton.BackgroundColor3 = Color3.fromRGB(0, 136, 255) TpButton.Position = UDim2.new(0.05, 0, 0.38, 0) TpButton.Size = UDim2.new(0.9, 0, 0, 35) TpButton.Font = Enum.Font.SourceSansBold TpButton.Text = "สิงร่างล็อกตัว: OFF" TpButton.TextColor3 = Color3.fromRGB(255, 255, 255) TpButton.TextSize = 14 KickButton.Name = "KickButton" KickButton.Parent = MainFrame KickButton.BackgroundColor3 = Color3.fromRGB(255, 38, 38) KickButton.Position = UDim2.new(0.05, 0, 0.52, 0) KickButton.Size = UDim2.new(0.9, 0, 0, 35) KickButton.Font = Enum.Font.SourceSansBold KickButton.Text = "เปิดระบบเตะ: OFF" KickButton.TextColor3 = Color3.fromRGB(255, 255, 255) KickButton.TextSize = 14 InstantButton.Name = "InstantButton" InstantButton.Parent = MainFrame InstantButton.BackgroundColor3 = Color3.fromRGB(138, 43, 226) InstantButton.Position = UDim2.new(0.05, 0, 0.69, 0) InstantButton.Size = UDim2.new(0.9, 0, 0, 45) InstantButton.Font = Enum.Font.SourceSansBold InstantButton.Text = "⚡ INSTANT TP-KICK ⚡" InstantButton.TextColor3 = Color3.fromRGB(255, 255, 255) InstantButton.TextSize = 15 DropdownFrame.Name = "DropdownFrame" DropdownFrame.Parent = MainFrame DropdownFrame.BackgroundColor3 = Color3.fromRGB(30, 30, 45) DropdownFrame.Position = UDim2.new(0.05, 0, 0.35, 0) DropdownFrame.Size = UDim2.new(0.9, 0, 0, 150) DropdownFrame.BorderSizePixel = 1 DropdownFrame.Visible = false DropdownFrame.ZIndex = 5 DropdownFrame.ScrollBarThickness = 6 UIListLayout.Parent = DropdownFrame UIListLayout.SortOrder = Enum.SortOrder.LayoutOrder local function UpdatePlayerList() for _, child in pairs(DropdownFrame:GetChildren()) do if child:IsA("TextButton") then child:Destroy() end end local count = 0 for _, player in pairs(Players:GetPlayers()) do if player ~= LocalPlayer then count = count + 1 local PButton = Instance.new("TextButton") PButton.Size = UDim2.new(1, 0, 0, 30) PButton.BackgroundColor3 = Color3.fromRGB(40, 40, 55) PButton.Font = Enum.Font.SourceSans PButton.Text = player.DisplayName .. " (@" .. player.Name .. ")" PButton.TextColor3 = Color3.fromRGB(255, 255, 255) PButton.TextSize = 13 PButton.ZIndex = 6 PButton.Parent = DropdownFrame PButton.MouseButton1Click:Connect(function() SystemConfig.TargetName = player.Name SelectedTargetLabel.Text = "เป้าหมาย: " .. player.DisplayName DropdownFrame.Visible = false Notify("Target", "เลือกเป้าหมาย: " .. player.DisplayName) end) end end DropdownFrame.CanvasSize = UDim2.new(0, 0, 0, count * 30) end ListButton.MouseButton1Click:Connect(function() DropdownFrame.Visible = not DropdownFrame.Visible if DropdownFrame.Visible then UpdatePlayerList() end end) Players.PlayerAdded:Connect(UpdatePlayerList) Players.PlayerRemoving:Connect(function(player) if player.Name == SystemConfig.TargetName then SystemConfig.TargetName = "" SelectedTargetLabel.Text = "เป้าหมาย: [ออกจากเกมไปแล้ว]" end UpdatePlayerList() end) local TpConnection, KickConnection local function ManageTeleport() if SystemConfig.TpEnabled then local MyChar = LocalPlayer.Character local MyRoot = MyChar and MyChar:FindFirstChild("HumanoidRootPart") if MyRoot and not SystemConfig.OriginalLocation then SystemConfig.OriginalLocation = MyRoot.CFrame end TpConnection = RunService.Heartbeat:Connect(function() if not SystemConfig.TpEnabled then return end local TargetPlayer = GetPlayerByUsername(SystemConfig.TargetName) local MyChar = LocalPlayer.Character local MyRoot = MyChar and MyChar:FindFirstChild("HumanoidRootPart") if TargetPlayer and TargetPlayer.Character and TargetPlayer.Character:FindFirstChild("HumanoidRootPart") and MyRoot then local TargetRoot = TargetPlayer.Character.HumanoidRootPart for _, part in pairs(MyChar:GetChildren()) do if part:IsA("BasePart") then part.CanCollide = false end end MyRoot.CFrame = TargetRoot.CFrame * CFrame.new(0, 0, 0.1) end end) else if TpConnection then TpConnection:Disconnect() end local MyChar = LocalPlayer.Character local MyRoot = MyChar and MyChar:FindFirstChild("HumanoidRootPart") if MyRoot and SystemConfig.OriginalLocation then MyRoot.CFrame = SystemConfig.OriginalLocation SystemConfig.OriginalLocation = nil end end end local function ManageKick() if SystemConfig.KickEnabled then KickConnection = RunService.Heartbeat:Connect(function() if not SystemConfig.KickEnabled then return end local MyChar = LocalPlayer.Character local MyRoot = MyChar and MyChar:FindFirstChild("HumanoidRootPart") if MyRoot then settings().Physics.AllowSleep = false LocalPlayer.MaximumSimulationRadius = math.huge setsimulationradius(math.huge) MyRoot.Velocity = Vector3.new(0, SystemConfig.KickForce, 0) MyRoot.RotVelocity = Vector3.new(SystemConfig.KickForce, SystemConfig.KickForce, SystemConfig.KickForce) RunService.RenderStepped:Wait() if MyRoot then MyRoot.Velocity = Vector3.new(0, 0, 0) MyRoot.RotVelocity = Vector3.new(0, 0, 0) end end end) else if KickConnection then KickConnection:Disconnect() end local MyChar = LocalPlayer.Character local MyRoot = MyChar and MyChar:FindFirstChild("HumanoidRootPart") if MyRoot then MyRoot.Velocity = Vector3.new(0, 0, 0) MyRoot.RotVelocity = Vector3.new(0, 0, 0) end if MyChar then for _, part in pairs(MyChar:GetChildren()) do if part:IsA("BasePart") then part.CanCollide = true end end end end end TpButton.MouseButton1Click:Connect(function() if SystemConfig.TargetName == "" then Notify("แจ้งเตือน", "กรุณาเลือกผู้เล่นก่อน!") return end SystemConfig.TpEnabled = not SystemConfig.TpEnabled if SystemConfig.TpEnabled then TpButton.Text = "สิงร่างล็อกตัว: ON" TpButton.BackgroundColor3 = Color3.fromRGB(46, 204, 113) else TpButton.Text = "สิงร่างล็อกตัว: OFF" TpButton.BackgroundColor3 = Color3.fromRGB(0, 136, 255) end ManageTeleport() end) KickButton.MouseButton1Click:Connect(function() SystemConfig.KickEnabled = not SystemConfig.KickEnabled if SystemConfig.KickEnabled then KickButton.Text = "เปิดระบบเตะ: ON" KickButton.BackgroundColor3 = Color3.fromRGB(46, 204, 113) else KickButton.Text = "เปิดระบบเตะ: OFF" KickButton.BackgroundColor3 = Color3.fromRGB(255, 38, 38) end ManageKick() end) local isExecutingInstant = false InstantButton.MouseButton1Click:Connect(function() if isExecutingInstant then return end local TargetPlayer = GetPlayerByUsername(SystemConfig.TargetName) if not TargetPlayer or not TargetPlayer.Character or not TargetPlayer.Character:FindFirstChild("HumanoidRootPart") then Notify("แจ้งเตือน", "ไม่พบเป้าหมาย หรือกรุณาเลือกชื่อผู้เล่นก่อน!") return end local MyChar = LocalPlayer.Character local MyRoot = MyChar and MyChar:FindFirstChild("HumanoidRootPart") if not MyRoot then return end isExecutingInstant = true local SavedLocation = MyRoot.CFrame Notify("Instant Kill", "กำลังวาร์ปเตะด่วน!") local StartTime = tick() local TempConnection TempConnection = RunService.Heartbeat:Connect(function() if tick() - StartTime >= 0.4 or not TargetPlayer.Character or not TargetPlayer.Character:FindFirstChild("HumanoidRootPart") then TempConnection:Disconnect() return end settings().Physics.AllowSleep = false LocalPlayer.MaximumSimulationRadius = math.huge setsimulationradius(math.huge) for _, part in pairs(MyChar:GetChildren()) do if part:IsA("BasePart") then part.CanCollide = false end end MyRoot.Velocity = Vector3.new(0, SystemConfig.KickForce, 0) MyRoot.RotVelocity = Vector3.new(SystemConfig.KickForce, SystemConfig.KickForce, SystemConfig.KickForce) MyRoot.CFrame = TargetPlayer.Character.HumanoidRootPart.CFrame end) task.wait(0.4) MyRoot.Velocity = Vector3.new(0, 0, 0) MyRoot.RotVelocity = Vector3.new(0, 0, 0) MyRoot.CFrame = SavedLocation for _, part in pairs(MyChar:GetChildren()) do if part:IsA("BasePart") then part.CanCollide = true end end isExecutingInstant = false Notify("Instant Kill", "เตะสำเร็จ! วาร์ปกลับจุดเดิมเรียบร้อย") end) LocalPlayer.CharacterAdded:Connect(function() SystemConfig.TpEnabled = false SystemConfig.KickEnabled = false SystemConfig.OriginalLocation = nil TpButton.Text = "สิงร่างล็อกตัว: OFF" TpButton.BackgroundColor3 = Color3.fromRGB(0, 136, 255) KickButton.Text = "เปิดระบบเตะ: OFF" KickButton.BackgroundColor3 = Color3.fromRGB(255, 38, 38) if TpConnection then TpConnection:Disconnect() end if KickConnection then KickConnection:Disconnect() end end)
